    let mut angle = x as i16;
    // Normalize modulo 360 (handle negative angles properly)
    angle = ((angle % 360) + 360) % 360;

    // We want to find r in {0,1,2,3} minimizing deviation,
    // where
    // A = (-angle + 90*r) mod 360
    // deviation = min(A, 360 - A)

    let mut best_r = 0u8;
